'use client';

import React from 'react';

/** Upload state for a file attachment. */
export type FileAttachmentState = 'uploading' | 'done' | 'error';

/** Props for the {@link FileAttachment} component. */
export interface FileAttachmentProps extends React.HTMLAttributes<HTMLDivElement> {
  /** File name. */
  name: string;
  /** Human-readable file size string (e.g. "2.4 MB"). */
  size?: string;
  /** File icon character or emoji. */
  icon?: string;
  /** Current upload state. */
  state?: FileAttachmentState;
  /** Upload progress (0-100). Drives the progress bar width via CSS variable. */
  progress?: number;
  /** Called when the remove button is clicked. */
  onRemove?: () => void;
  /** Additional CSS class names. */
  className?: string;
}

/**
 * File upload pill with progress bar and remove button.
 * Renders a `<div>` with `sk-file-attachment` and `data-state`.
 */
export const FileAttachment = React.forwardRef<HTMLDivElement, FileAttachmentProps>(
  ({ name, size, icon, state, progress, onRemove, className, ...rest }, ref) => (
    <div
      ref={ref}
      className={`sk-file-attachment${className ? ` ${className}` : ''}`}
      data-state={state}
      style={{ '--_progress': progress !== undefined ? `${progress}%` : undefined } as React.CSSProperties}
      {...rest}
    >
      <div className="sk-file-attachment__progress" />
      {icon && <span className="sk-file-attachment__icon">{icon}</span>}
      <span className="sk-file-attachment__name">{name}</span>
      {size && <span className="sk-file-attachment__size">{size}</span>}
      {onRemove && (
        <button className="sk-file-attachment__remove" onClick={onRemove} aria-label="Remove file">
          x
        </button>
      )}
    </div>
  ),
);

FileAttachment.displayName = 'FileAttachment';

/** Props for the {@link FileAttachments} list wrapper. */
export interface FileAttachmentsProps extends React.HTMLAttributes<HTMLDivElement> {
  children?: React.ReactNode;
  className?: string;
}

/** Flex-wrap container for multiple FileAttachment pills. */
export const FileAttachments = React.forwardRef<HTMLDivElement, FileAttachmentsProps>(
  ({ className, children, ...rest }, ref) => (
    <div ref={ref} className={`sk-file-attachments${className ? ` ${className}` : ''}`} {...rest}>
      {children}
    </div>
  ),
);

FileAttachments.displayName = 'FileAttachments';

/**
 * skeehn — FileAttachment Component
 *
 * @component sk-file-attachment
 * @states    [data-state="uploading"] | [data-state="error"] | [data-state="done"] | [data-skeleton]
 * @slots     __progress | __icon | __name | __size | __remove
 * @container sk-file-attachments (flex wrapper for multiple files)
 * @features  Upload progress bar, state variants, remove button, truncated name
 * @a11y      Focus-visible on remove, state conveyed by border color + text
 * @print     Hidden (interactive file controls)
 */

.sk-file-attachment {
  display: inline-flex;
  align-items: center;
  gap: var(--sk-space-2);
  padding: var(--sk-space-1) var(--sk-space-2) var(--sk-space-1) var(--sk-space-3);
  border: 1px solid hsl(var(--sk-border-color));
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  color: hsl(var(--sk-foreground));
  background: hsl(var(--sk-surface));
  max-width: 300px;
  position: relative;
  overflow: hidden;
}

/* Progress bar (CSS var driven) */
.sk-file-attachment__progress {
  position: absolute;
  bottom: 0;
  left: 0;
  height: 2px;
  background: hsl(var(--sk-primary));
  width: var(--_progress, 0%);
  transition: width 0.2s ease;
}
.sk-file-attachment[data-state="uploading"] .sk-file-attachment__progress {
  animation: sk-progress-indeterminate 1.2s ease infinite;
}
@keyframes sk-progress-indeterminate {
  0%   { left: 0%;   width: 30%; }
  50%  { left: 35%;  width: 60%; }
  100% { left: 100%; width: 0%;  }
}

/* State variants */
.sk-file-attachment[data-state="uploading"] {
  border-color: hsl(var(--sk-muted-foreground) / 0.4);
  opacity: 0.8;
}
.sk-file-attachment[data-state="error"] {
  border-color: hsl(var(--sk-destructive));
  color: hsl(var(--sk-destructive));
}
.sk-file-attachment[data-state="done"] {
  border-color: hsl(var(--sk-success) / 0.5);
}

.sk-file-attachment__icon {
  flex-shrink: 0;
  font-size: 0.875rem;
  opacity: 0.6;
}
.sk-file-attachment__name {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.sk-file-attachment__size {
  flex-shrink: 0;
  opacity: 0.4;
  font-size: 9px;
}
.sk-file-attachment__remove {
  flex-shrink: 0;
  background: none;
  border: none;
  padding: 2px 4px;
  cursor: pointer;
  color: hsl(var(--sk-muted-foreground));
  font-family: var(--sk-font-mono);
  font-size: var(--sk-font-size-xs);
  line-height: 1;
  transition: color var(--sk-transition);
}
.sk-file-attachment__remove:hover  { color: hsl(var(--sk-destructive)); }
.sk-file-attachment__remove:focus-visible {
  outline: 2px solid hsl(var(--sk-ring));
  outline-offset: 2px;
}

/* List wrapper for multiple files */
.sk-file-attachments {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sk-space-2);
  padding: var(--sk-space-2) 0;
}

/* Micro-interactions */
.sk-file-attachment { transition: transform var(--sk-transition-fast), border-color var(--sk-transition-fast); }
.sk-file-attachment:hover { transform: translateY(-1px); }

/* Skeleton */
.sk-file-attachment[data-skeleton] {
  pointer-events: none;
  color: transparent;
  background: linear-gradient(90deg, hsl(var(--sk-muted)) 25%, hsl(var(--sk-accent)) 50%, hsl(var(--sk-muted)) 75%);
  background-size: 200% 100%;
  animation: sk-card-shimmer 1.8s ease-in-out infinite;
  border-color: transparent;
  min-width: 8rem;
  min-height: 1.5rem;
}

.sk-file-attachment[data-skeleton] .sk-file-attachment__remove { display: none; }
.sk-file-attachment[data-skeleton] .sk-file-attachment__progress { display: none; }

@media print { .sk-file-attachment { display: none; } .sk-file-attachments { display: none; } }

@media (prefers-reduced-motion: reduce) {
  .sk-file-attachment__progress { animation: none; }
  .sk-file-attachment__remove   { transition: none; }
  .sk-file-attachment { transition: none; }
  .sk-file-attachment:hover { transform: none; }
  .sk-file-attachment[data-skeleton] { animation: none; background: hsl(var(--sk-muted)); }
}
